      }
    },
    {
      "id": "3",
      "type": "template-transform",
      "param": {
        "variables": [
          ["summaries", ["output", "2"]]
        ],
        "template": "# Document Summaries\n\n{% for s in summaries %}\n## Summary for Document {{ loop.index }}\n{{ s }}\n\n{% endfor %}"
      }
    },
    {
      "id": "4",
      "type": "markdown-exporter",
      "param": {
        "target_type": "docx",
        "md_text": "{{#3.output#}}"
      }
    },
    {
      "id": "5",
      "type": "list-operator",
      "param": {
        "variable": ["files", "4"],
        "operator": ["extract_by", 1]
      }
    },
    {
      "id": "6",
      "type": "end",
      "param": {
        "outputs": [
          ["summary", ["output", "3"]],
          ["docx_file", ["first_record", "5"]]
        ]
      }
    }
  ],
  "edges": [
    ["1", 0, "2"],
    ["2-1", 0, "2-2"],
