      }
    },
    {
      "id": "4-3",
      "type": "llm",
      "param": {
        "system": "You are an expert document analyzer. Parse structure, analyze content, and summarize documents.",
        "user": "Analyze this document:\n{{#4-2.text#}}\n1. Parse structure\n2. Analyze each part\n3. Provide summary"
