        "template": "# Combined Summaries\n\n## Documents\n{% for s in doc_summaries %}\n### Document {{ loop.index }}\n{{ s }}\n\n{% endfor %}\n## Images\n{% for s in img_summaries %}\n### Image {{ loop.index }}\n{{ s }}\n\n{% endfor %}"
